document.addEventListener("DOMContentLoaded", () => {
  let e = document.querySelector(".gallery"),
    a = [...e.querySelectorAll(".gallery-item")],
    l = document.createElement("div");
  (l.className = "gallery-items-row row"),
    e.appendChild(l),
    a.forEach((e) => {
      e.classList.add("img-fluid");
      let a = document.createElement("div");
      (a.className = "item-column mb-4 col-12 col-sm-6 col-md-4"),
        a.appendChild(e),
        l.appendChild(a);
    });
  let t = new Set();
  a.forEach((e) => {
    t.add(e.dataset.galleryTag);
  });
  let s = [...t],
    i = document.createElement("ul");
  (i.className = "my-4 tags-bar nav nav-pills"),
    (i.innerHTML = `<li class="nav-item">
      <span class="nav-link active active-tag" data-images-toggle="all">Tous</span>
    </li>`),
    s.forEach((e) => {
      i.innerHTML += `<li class="nav-item">
        <span class="nav-link" data-images-toggle="${e}">${e}</span>
      </li>`;
    }),
    e.insertBefore(i, l),
    i.querySelectorAll(".nav-link").forEach((e) => {
      e.addEventListener("click", () => {
        if (e.classList.contains("active-tag")) return;
        i
          .querySelector(".active-tag")
          ?.classList.remove("active", "active-tag"),
          e.classList.add("active", "active-tag");
        let a = e.dataset.imagesToggle;
        l.querySelectorAll(".item-column").forEach((e) => {
          let l = e.querySelector(".gallery-item"),
            t = "all" === a || l.dataset.galleryTag === a;
          e.style.display = t ? "block" : "none";
        });
      });
    }),
    (e.style.display = "block");
});
